package disposable

import (
	_ "embed"
	"sort"
	"strings"
	"sync"

	"golang.org/x/net/idna"
	"golang.org/x/net/publicsuffix"
)

// The data files are generated by cmd/update-lists. See data/SOURCES.md.

//go:embed data/disposable.txt
var disposableData string

//go:embed data/relay.txt
var relayData string

//go:embed data/allowlist.txt
var allowData string

// domainSet is a sorted list of domains searched with binary search.
// The strings point into the embedded data, so loading copies nothing
// but the slice headers.
type domainSet []string

func parseDomainSet(data string) domainSet {
	set := make(domainSet, 0, strings.Count(data, "\n")+1)
	for _, line := range strings.Split(data, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		set = append(set, line)
	}
	if !sort.StringsAreSorted(set) {
		sort.Strings(set)
	}
	return set
}

func (s domainSet) has(domain string) bool {
	i := sort.SearchStrings(s, domain)
	return i < len(s) && s[i] == domain
}

var (
	loadOnce   sync.Once
	disposable domainSet
	relay      domainSet
	allow      domainSet
)

func load() {
	loadOnce.Do(func() {
		disposable = parseDomainSet(disposableData)
		relay = parseDomainSet(relayData)
		allow = parseDomainSet(allowData)
	})
}

// Category says what kind of mail service a domain belongs to.
type Category int

const (
	// CategoryNone means the domain is not on any list.
	CategoryNone Category = iota

	// CategoryDisposable means a throwaway mailbox service (Mailinator,
	// Guerrilla Mail, temp-mail and the like).
	CategoryDisposable

	// CategoryRelay means a forwarding or alias service (DuckDuckGo Email
	// Protection, SimpleLogin, addy.io, Firefox Relay, Apple Hide My Email and
	// the like). These are usually real people protecting their privacy, so
	// whether to accept them is the caller's decision.
	CategoryRelay
)

func (c Category) String() string {
	switch c {
	case CategoryDisposable:
		return "disposable"
	case CategoryRelay:
		return "relay"
	default:
		return "none"
	}
}

// candidates returns domain and its parent domains, most specific first,
// stopping at the registrable domain (eTLD+1) so that a list entry can never
// match a whole public suffix such as co.uk.
func candidates(domain string) []string {
	out := []string{domain}
	reg, err := publicsuffix.EffectiveTLDPlusOne(domain)
	if err != nil || reg == domain {
		return out
	}
	for d := domain; d != reg; {
		i := strings.IndexByte(d, '.')
		if i < 0 {
			break
		}
		d = d[i+1:]
		out = append(out, d)
	}
	return out
}

// classify expects a lower-case ASCII (punycode) domain.
func classify(domain string) Category {
	load()
	// The most specific match wins, so an allowlisted subdomain of a listed
	// domain (or the other way round) behaves as expected.
	for _, d := range candidates(domain) {
		switch {
		case allow.has(d):
			return CategoryNone
		case relay.has(d):
			return CategoryRelay
		case disposable.has(d):
			return CategoryDisposable
		}
	}
	return CategoryNone
}

// ClassifyDomain returns the category of an email domain, matching parent
// domains too: foo.mailinator.com is disposable because mailinator.com is.
// Unicode domains are converted to punycode first. Invalid domains return
// CategoryNone.
func ClassifyDomain(domain string) Category {
	domain, err := idna.ToASCII(strings.ToLower(strings.TrimSpace(domain)))
	if err != nil {
		return CategoryNone
	}
	domain = strings.TrimSuffix(domain, ".")
	if !ValidateDomain(domain) {
		return CategoryNone
	}
	return classify(domain)
}

// IsDisposableDomain reports whether domain (or a parent of it) belongs to a
// disposable email service. Relay services are not included; see IsRelayDomain.
func IsDisposableDomain(domain string) bool {
	return ClassifyDomain(domain) == CategoryDisposable
}

// IsRelayDomain reports whether domain (or a parent of it) belongs to an email
// forwarding or alias service.
func IsRelayDomain(domain string) bool {
	return ClassifyDomain(domain) == CategoryRelay
}

// ListSizes returns the number of entries in the embedded lists. It is meant
// for logging and sanity checks.
func ListSizes() (disposableCount, relayCount, allowCount int) {
	load()
	return len(disposable), len(relay), len(allow)
}
